/* Inzira service worker - offline first.
 * Bump CACHE when you change any file in CORE or the question bank/images.
 */
const CACHE = "inzira-v23";
const CORE = [
  "./",
  "index.html",
  "styles.css",
  "app.js",
  "auth.js",
  "sync.js",
  "manifest.webmanifest",
  "data/cloud.config.js",
  "data/schools.js",
  "data/bank.js",
  "data/signs.js",
  "data/precache.js",
  "assets/icon.svg",
  "assets/icon-192.png",
  "assets/icon-512.png",
  "assets/icon-maskable-512.png"
];

// Question images are listed in data/precache.js, generated by tools/build_data.py,
// so the whole bank is available offline as soon as the app is installed.
importScripts("./data/precache.js");
const IMAGES = self.INZIRA_PRECACHE || [];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then(async (cache) => {
      await cache.addAll(CORE);
      // Best effort: one missing image must not fail the whole install.
      await Promise.allSettled(IMAGES.map((url) => cache.add(url)));
      await self.skipWaiting();
    })
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;

  // Navigations: serve the cached shell for the app itself, and let every
  // other page (e.g. tools/review.html) reach the network normally.
  if (req.mode === "navigate") {
    const path = new URL(req.url).pathname;
    if (path === "/" || path.endsWith("/index.html")) {
      event.respondWith(
        caches.match("index.html").then((hit) => hit || fetch(req))
      );
    }
    return;
  }

  event.respondWith(
    caches.match(req).then((hit) => {
      if (hit) {
        // Refresh in the background when online.
        fetch(req).then((res) => {
          if (res && res.ok) caches.open(CACHE).then((c) => c.put(req, res));
        }).catch(() => {});
        return hit;
      }
      return fetch(req).then((res) => {
        if (res && res.ok && new URL(req.url).origin === location.origin) {
          const copy = res.clone();
          caches.open(CACHE).then((c) => c.put(req, copy));
        }
        return res;
      });
    })
  );
});
